/**
 * KS-963 (widened) — `getUserByIdPreAuth` must not report a DB failure as
 * "no such user".
 *
 * Kam ruled `include` on 2026-09-09 07:08: *"Widen #907 to getUserByIdPreAuth
 * now — two lines, same pattern, same round."* #907 had already merged, so the
 * widening lands separately; the decision is his.
 *
 * The pattern is the same as the sibling, byte-for-byte: `fromRow` is `async`
 * and is returned from inside the `try` WITHOUT `await`, so neither catch ever
 * saw a decrypt rejection — both close the `query()` failure path.
 *
 * ⚠ WHY THIS MATTERS MORE THAN A SHARED SHAPE SUGGESTS. There are FIVE callers.
 * Four read `null` as "the user does not exist" and two of those DESTROY a
 * credential on it; the fifth reads `null` as "no tenant context". The
 * consequence cells at the bottom pin that, because the two-line diff does not:
 *
 *   routes/auth.ts:816   password reset  -> consumed the reset token, then 404
 *   routes/auth.ts:859   email verify    -> consumed the email token, then 404
 *   routes/wallet.ts:193 wallet sign-in  -> fell through into `createUser`
 *   routes/auth.ts:686   token refresh   -> InvalidCredentialsError (logged out)
 *   userRepo.ts:859      updateUser      -> 200 "Password has been reset
 *                                          successfully" over an UPDATE issued
 *                                          with `tenant undefined`; and on the
 *                                          LOGIN success path (auth.ts:587, the
 *                                          unguarded `lastLoginAt` write) a
 *                                          silent miss -> now a 503 with NO
 *                                          UPDATE issued (the FIFTH-CALLER
 *                                          cells at the bottom pin it)
 *
 *   Line numbers are the REBASED tree's (develop `163ca2c74` + this branch),
 *   not #913's base — the enumeration and its `:800` were written against
 *   `f9296f9ea`, 100+ commits ago (KS-963 r2).
 *
 * An earlier version of this header said FOUR. The fifth is an INTRA-module call
 * with no `userRepo.` qualifier, so a symbol grep cannot see it; the #913 tier-1
 * gate found it with a TypeScript LanguageService reference walk, and
 * `ks468-authenticate-tenant-guc.test.ts:139` had named five all along.
 *
 * ⚠ The PRE-CHANGE wallet outcome on an EXISTING row is NOT established — the
 * gate's harness never executed the INSERT (no `PII_ENCRYPTION_KEY`). Only the
 * fall-through into `createUser` is established. No cell below claims otherwise.
 *
 * Both consumes sit INSIDE the `if (!user)` branch, so a throw never reaches
 * them. That ordering is the whole value of the change and it is asserted here
 * rather than asserted in prose.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

const mockQuery = vi.hoisted(() => vi.fn());
vi.mock('../db', () => ({
  query: mockQuery,
  isDbAvailable: () => true,
  getPool: () => ({}),
}));
vi.mock('../utils/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

import { getUserByIdPreAuth, updateUser } from '../repositories/userRepo';

const ID = 'a0000000-0000-4000-8000-000000000020';

beforeEach(() => vi.clearAllMocks());

describe('KS-963 widened — getUserByIdPreAuth no longer swallows DB failures', () => {
  it.each([
    ['pool starvation (53300 too_many_connections)', { code: '53300', message: 'too many connections' }],
    ['connection exception (class 08)', { code: '08006', message: 'connection failure' }],
    ['admin shutdown (57P01)', { code: '57P01', message: 'admin shutdown' }],
    ['socket refused (ECONNREFUSED)', { code: 'ECONNREFUSED', message: 'connect ECONNREFUSED' }],
    ['pool acquisition timeout (no code)', { message: 'Connection terminated due to connection timeout' }],
  ])('throws a 503 SERVICE_UNAVAILABLE on %s — never null', async (_label, err) => {
    mockQuery.mockRejectedValueOnce(Object.assign(new Error((err as any).message), err));
    // Asserting the CONTRACT (statusCode/code), not instanceof — matching
    // dbErrors.test.ts:82, which documents why: the AppError base constructor
    // pins the prototype to AppError.prototype, so instanceof fails for every
    // subclass. Pre-existing, and the error handler correctly keys off
    // `instanceof AppError` + statusCode.
    await expect(getUserByIdPreAuth(ID)).rejects.toMatchObject({
      statusCode: 503,
      code: 'SERVICE_UNAVAILABLE',
    });
  });

  it('RETHROWS a non-infrastructure DB error rather than returning null', async () => {
    // 22P02 is a query-level error: not availability, so not a 503 — but still
    // not "no such user", which is the whole point of the ruling.
    const err = Object.assign(new Error('invalid input syntax for type uuid'), { code: '22P02' });
    mockQuery.mockRejectedValueOnce(err);
    await expect(getUserByIdPreAuth(ID)).rejects.toThrow('invalid input syntax for type uuid');
    // and it is NOT dressed up as a 503 — a query bug is not an outage.
    mockQuery.mockRejectedValueOnce(err);
    const thrown: any = await getUserByIdPreAuth(ID).catch((e) => e);
    expect(thrown.statusCode).toBeUndefined();
    expect(thrown.code).toBe('22P02');
  });

  it('CONTROL: a genuine no-rows result still returns null — absence is still absence', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [] });
    await expect(getUserByIdPreAuth(ID)).resolves.toBeNull();
  });

  it('CONTROL: a found row is still returned — the happy path is untouched', async () => {
    mockQuery.mockResolvedValueOnce({
      rows: [{ id: ID, email: 'admin@secuura.com', role: 'SYSTEM_ADMIN', status: 'ACTIVE' }],
    });
    const user = await getUserByIdPreAuth(ID);
    expect(user).not.toBeNull();
    expect(user!.id).toBe(ID);
  });
});

/**
 * The consequence the two-line diff does not show. These pin the ORDERING that
 * makes the change worth making: the credential-destroying calls live inside
 * the `if (!user)` branch, so a throw from the lookup cannot reach them.
 *
 * ⚠ KS-963 F-3 (#913 tier-1 gate). The first version of these three cells COULD
 * NOT FAIL on the defect they exist to detect. `indexOf(needle, guard)` finds
 * ANY later occurrence, and each handler has THREE consumes — expiry, !user,
 * success. Moving the !user consume out of its guard to before the lookup — the
 * exact defect — left the SUCCESS-PATH consume to satisfy `consume > guard`,
 * and all 11 cells stayed GREEN. The declared control was measured not to
 * discriminate either: it picked the expiry consume, which precedes the lookup
 * under the tamper AND under the fix, so it is true in both worlds.
 *
 * The rewrite below is bounded rather than positional. Two properties, and a
 * tamper that breaks the ordering must break at least one:
 *
 *   1. the !user consume is INSIDE the brace-matched `if (!user)` block, so a
 *      sibling occurrence elsewhere in the file cannot stand in for it; and
 *   2. the expiry consume is the ONLY consume before the lookup, so hoisting a
 *      second one above the lookup reds even if a copy stays in the guard.
 *
 * Property 2 is what makes property 1 non-defeatable, which is the half the
 * original was missing.
 */

/**
 * The body of the block opened by the first `{` at or after `from`, brace-matched
 * and excluding the braces. String literals and comments are skipped so a brace
 * inside either cannot unbalance the count.
 */
function braceBlock(src: string, from: number): string {
  const start = src.indexOf('{', from);
  if (start < 0) return '';
  let depth = 0;
  let i = start;
  while (i < src.length) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') {
      const nl = src.indexOf('\n', i);
      if (nl < 0) break;
      i = nl;
      continue;
    }
    if (c === '/' && src[i + 1] === '*') {
      const end = src.indexOf('*/', i + 2);
      i = end < 0 ? src.length : end + 2;
      continue;
    }
    if (c === "'" || c === '"' || c === '`') {
      const quote = c;
      i++;
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') i++;
        i++;
      }
      i++;
      continue;
    }
    if (c === '{') depth++;
    else if (c === '}') {
      depth--;
      if (depth === 0) return src.slice(start + 1, i);
    }
    i++;
  }
  return '';
}

const count = (haystack: string, needle: string) => haystack.split(needle).length - 1;

const readRoute = (file: string) =>
  import('node:fs').then((fs) => fs.readFileSync(new URL(`../routes/${file}`, import.meta.url), 'utf8'));

/**
 * Both token handlers have the identical shape, so they are asserted identically:
 * expiry consume -> lookup -> `if (!user)` { consume } -> success consume.
 */
function assertConsumeIsGuarded(src: string, consumeFn: string, lookupFrom: number) {
  const lookup = src.indexOf('getUserByIdPreAuth(stored.userId)', lookupFrom);
  // Without this the cell is satisfied by a file where the lookup is ABSENT:
  // indexOf returns -1 and every later comparison still holds. (F-3, cell 2.)
  expect(lookup).toBeGreaterThan(-1);

  const guard = src.indexOf('if (!user) {', lookup);
  expect(guard).toBeGreaterThan(lookup);

  // PROPERTY 1 — the consume is inside the guard's own block, not merely
  // somewhere after it. A sibling occurrence cannot satisfy this.
  const guardBody = braceBlock(src, guard);
  expect(guardBody).not.toBe('');
  expect(guardBody).toContain(consumeFn);

  // PROPERTY 2 — the expiry-branch consume is the ONLY one before the lookup.
  // This is what reds when the guarded consume is hoisted above the lookup,
  // even if a copy is left behind in the guard.
  // Searched BACKWARDS from the lookup: the caller's `lookupFrom` anchor for the
  // email handler is the expiry consume itself, which is inside this very block,
  // so a forward search from it misses the guard that opens two lines above.
  const expiryGuard = src.lastIndexOf('if (new Date() > stored.expiresAt) {', lookup);
  expect(expiryGuard).toBeGreaterThan(-1);
  expect(expiryGuard).toBeLessThan(lookup);
  const expiryBody = braceBlock(src, expiryGuard);
  expect(count(expiryBody, consumeFn)).toBe(1);
  expect(count(src.slice(expiryGuard, lookup), consumeFn)).toBe(1);
}

describe('KS-963 widened — a DB failure no longer burns a single-use token', () => {
  it('the reset-token consume is INSIDE the !user branch, so a throw precedes it', async () => {
    const src = await readRoute('auth.ts');
    assertConsumeIsGuarded(src, 'consumeResetToken', 0);
  });

  it('the email-token consume has the same ordering', async () => {
    const src = await readRoute('auth.ts');
    // KS-963 r2 (#913 review, housekeeping ii): the anchor used to be the bare
    // symbol `consumeEmailToken`. A top-level `import { consumeEmailToken }`
    // slid it to the import, the lookup found became the RESET handler's, and
    // the cell went RED on an unrelated edit (measured, s202). Anchoring on the
    // route registration pins the search to the verify-email handler itself.
    const handler = src.indexOf("post('/verify-email'");
    expect(handler).toBeGreaterThan(-1);
    assertConsumeIsGuarded(src, 'consumeEmailToken', handler);
  });

  it('in getOrCreateWalletUser NOTHING is written before the lookup — not just createUser', async () => {
    const src = await readRoute('wallet.ts');
    const fn = src.slice(src.indexOf('async function getOrCreateWalletUser'));
    const body = fn.slice(0, fn.indexOf('\n}\n'));
    const lookup = body.indexOf('getUserByIdPreAuth');
    const create = body.indexOf('createUser(');
    expect(lookup).toBeGreaterThan(-1);
    expect(create).toBeGreaterThan(lookup);

    // KS-963 F-4: asserting only that `createUser(` follows the lookup leaves the
    // cell GREEN when a DIFFERENT write is inserted above it, while partial state
    // is exactly as possible. So this is an ALLOW-SET over everything awaited
    // before the lookup, not an enumeration of write verbs — an enumeration fails
    // OPEN on the verb nobody thought of (the KS-945 class), an allow-set fails
    // CLOSED. Adding a genuine read here is meant to red this cell until the call
    // is named below.
    const awaitedBeforeLookup = [...body.slice(0, lookup).matchAll(/await\s+([A-Za-z_$][\w$.]*)\s*\(/g)].map(
      (m) => m[1],
    );
    expect(awaitedBeforeLookup).toEqual(['query']);

    // ...and the one call allowed above is a read, pinned to the statement itself
    // rather than to its name.
    expect(body.slice(0, lookup)).toContain('SELECT * FROM auth_find_user_by_wallet');
  });
});

/**
 * KS-963 r2 — the FIFTH caller, the one #913's enumeration missed and its
 * review asked for (a cell, or an explicit acceptance of the louder failure).
 *
 * `updateUser` resolves the row's tenant PRE-AUTH through `getUserByIdPreAuth`
 * (`tenantForRls = currentTenantId() ? undefined : (await
 * getUserByIdPreAuth(id))?.tenantId`). On the LOGIN success path
 * (`routes/auth.ts:587`, `updateUser(user.id, { lastLoginAt })`, no try/catch)
 * that lookup used to swallow an infrastructure failure into `null`: the UPDATE
 * was still issued with `tenant undefined`, `lastLoginAt` was silently not
 * recorded, and the login answered 200. Now the lookup throws 503 and NO UPDATE
 * is issued — the louder failure is the ruled behaviour, and this cell pins it.
 *
 * The db stub is an SQL-keyed dispatcher rather than a `mockRejectedValueOnce`
 * so that the PRE-FIX path runs to completion (swallow -> UPDATE -> read-back
 * -> resolves null) and the red is the assertion's, not `undefined.rowCount`.
 * Measured red-first at develop `163ca2c74`: "promise resolved null instead of
 * rejecting". `mockReset` after each cell so the dispatcher never leaks into
 * the once-queued cells above.
 */
describe('KS-963 r2 — the fifth caller: updateUser resolves its own tenant pre-auth', () => {
  const LOOKUP = 'auth_find_user_by_id';
  const isLookup = (sql: unknown) => String(sql).includes(LOOKUP);
  const FIFTH_ID = 'a0000000-0000-4000-8000-000000000063';

  afterEach(() => mockQuery.mockReset());

  it('F1 an infrastructure failure of the carve-out lookup rejects 503 and issues NO UPDATE', async () => {
    mockQuery.mockImplementation(async (sql: unknown) => {
      if (isLookup(sql)) throw Object.assign(new Error('connect ECONNREFUSED'), { code: 'ECONNREFUSED' });
      return { rows: [], rowCount: 1 };
    });
    await expect(updateUser(FIFTH_ID, { lastLoginAt: new Date() })).rejects.toMatchObject({
      statusCode: 503,
      code: 'SERVICE_UNAVAILABLE',
    });
    // Exactly ONE statement, and it is the lookup: the UPDATE was never issued.
    expect(mockQuery).toHaveBeenCalledTimes(1);
    expect(String(mockQuery.mock.calls[0][0])).toContain(LOOKUP);
  });

  it("F2 CONTROL: a resolved row's tenant_id reaches the UPDATE as query()'s third argument", async () => {
    // Proves the branch is LIVE in this harness (currentTenantId() is falsy, so
    // the pre-auth lookup is the first statement) — F1 cannot pass by never
    // reaching the lookup at all.
    mockQuery.mockImplementation(async (sql: unknown) => {
      if (isLookup(sql)) {
        return {
          rows: [{ id: FIFTH_ID, email: 'fifth@example.com', role: 'ISSUER', status: 'ACTIVE', tenant_id: 'tenant-A' }],
          rowCount: 1,
        };
      }
      return { rows: [], rowCount: 1 };
    });
    await updateUser(FIFTH_ID, { lastLoginAt: new Date() });
    const update = mockQuery.mock.calls.find((c) => String(c[0]).startsWith('UPDATE users'));
    expect(update).toBeDefined();
    expect(update![2]).toBe('tenant-A');
    expect(String(mockQuery.mock.calls[0][0])).toContain(LOOKUP);
  });
});

// =============================================================================
// S130-F6 — PUT `auth.openapi.ts` IN A TEST'S IMPORT GRAPH, so its module-scope
// canary can actually fire
// =============================================================================
//
// #820 added a module-scope guard to `auth.openapi.ts` and recorded it as a
// canary. The re-gate measured it and it does not red: 456/456 at the head,
// 488/488 on the merged tree. The reason is not that the guard is wrong — it is
// that NOTHING IMPORTS THE MODULE. Its own header says so:
//
//   "This also means the gate's canary still stands: a module-scope throw in
//    this file leaves the auth suite green, because it is in no test's import
//    graph."
//
// Two existing tests mention `auth.openapi.ts` in prose. Neither imports it.
// A guard in a module no test loads is a guard that cannot run, which is the
// same class as KS-781 P3-3 itself — a control-byte guard mounted where it
// could never see a body.
//
// This file's whole job is to be the import. The assertions are deliberately
// thin: the SUBJECT is module evaluation, and anything that throws at module
// scope fails this file before an assertion is reached. That is the point.
//
// ⚠ If this file ever goes red for a reason that is NOT a deliberate canary,
// read the header of `auth.openapi.ts` first: it documents a live zod-prototype
// hazard (`extendZodWithOpenApi` landing on a different prototype under vitest
// than under the CJS spec generator). That is a real, separately-filed problem
// and this file will surface it — which is better than the silence it replaces.
// =============================================================================

import { describe, it, expect } from 'vitest';

describe('S130-F6 — the auth OpenAPI module is loaded by the test suite', () => {
  it('imports auth.openapi.ts without throwing at module scope', async () => {
    // The import IS the test. A module-scope throw — the canary, or a real
    // regression in the registrations — fails here instead of passing silently.
    const mod = await import('../auth.openapi');
    expect(mod, 'the module evaluated').toBeTruthy();
  });

  it('CONTROL — the import actually registered paths, so a no-op module would not pass', async () => {
    // Without this, an `auth.openapi.ts` gutted to an empty file would satisfy
    // the case above. The registry is the observable side effect of evaluating
    // the module, so it is what proves the evaluation did something.
    await import('../auth.openapi');
    const { sharedRegistry } = await import('@secuura/shared');
    const paths = (sharedRegistry as unknown as { definitions: Array<{ route?: { path?: string } }> })
      .definitions.filter((d) => d.route?.path).map((d) => d.route!.path!);
    expect(paths.length, 'the registry holds registered routes').toBeGreaterThan(0);
    expect(
      paths.some((p) => p.startsWith('/api/auth/')),
      'and among them are this module\'s own /api/auth/* registrations',
    ).toBe(true);
  });
});
